// Bundles the toolbar (src/toolbar-client.ts, which runs in visitors' pages)
// into src/toolbar-bundle.gen.ts as a string the Worker serves. Run after
// changing the client: `bun run apps/worker/scripts/toolbar.ts`. A test fails
// when the generated file is out of date.

const here = new URL(".", import.meta.url).pathname;
export const CLIENT = here + "../src/toolbar-client.ts";
export const OUT = here + "../src/toolbar-bundle.gen.ts";

export async function bundleToolbar(): Promise<string> {
  const result = await Bun.build({
    entrypoints: [CLIENT],
    target: "browser",
    format: "esm",
    minify: true,
    sourcemap: "none",
  });
  if (!result.success) throw new AggregateError(result.logs, "toolbar bundle failed");
  return (await result.outputs[0]!.text()).trim();
}

export function generated(js: string): string {
  return `// Generated by scripts/toolbar.ts from toolbar-client.ts. Don't edit.\nexport const TOOLBAR_BUNDLE = ${JSON.stringify(js)};\n`;
}

if (import.meta.main) {
  await Bun.write(OUT, generated(await bundleToolbar()));
  console.log("src/toolbar-bundle.gen.ts");
}
